from attrs import define

@define(frozen=True)
class MyException(Exception):
    message: str

def test_frozen_exception_mutation():
    exc = MyException(message="An error occurred")

    # These should be mutable even if frozen
    try:
        exc.__suppress_context__ = True
        print("Successfully set __suppress_context__")
    except Exception as e:
        print(f"Failed to set __suppress_context__: {e}")
        raise e

    try:
        exc.__notes__ = "Some notes"
        print("Successfully set __notes__")
    except Exception as e:
        print(f"Failed to set __notes__: {e}")
        raise e

if __name__ == "__main__":
    try:
        test_frozen_exception_mutation()
        print("REPRO PASS")
    except Exception:
        print("REPRO FAIL")

